const alert = $input.first().json;
const url = String(alert.url || '').trim();
const token = ($env.FLEET_COMMAND_TOKEN || '').trim();
const headers = { 'Content-Type': 'application/json' };
if (token) headers['Authorization'] = 'Bearer ' + token;
let dup = false;
if (url) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:8080/api/seen',
      headers,
      body: JSON.stringify({ key: 'phish|' + alert.agent_id + '|' + url.toLowerCase(), window_secs: 600 }),
      timeout: 8000,
    });
    dup = Boolean(resp && resp.duplicate);
  } catch (e) { /* fail-open */ }
}
return [{ json: { ...alert, _cacheHit: dup, _cachedStats: null } }];

// patch:tglog:v1 — catat alert Telegram yang benar-benar terkirim.
// Bot API tak punya histori keluar; kirim ringkasan ke service alert-log.
const inp = $input.first().json;
const rec = { ts: new Date().toISOString(), workflow: 'Deteksi Phishing', node: 'Send Telegram Info' };
try {
  const r = inp.result || inp;
  rec.telegram_ok = (inp.ok === true) || !!r.message_id;
  rec.message_id = r.message_id || null;
  rec.chat_id = (r.chat && r.chat.id) || null;
} catch (e) {}
for (const nm of ['Build Payload', 'Rangkum Hasil', 'Rangkum Chain']) {
  try {
    const p = $(nm).first().json;
    rec.severity = rec.severity || p.severity || p.severityLabel;
    rec.agent = rec.agent || p.agent || p.agentName;
    rec.hash = rec.hash || p.hash;
    rec.path = rec.path || p.filePath || p.path;
    rec.title = rec.title || p.title || p.subject;
    break;
  } catch (e) {}
}
try {
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://host.docker.internal:8091/log', headers: Object.assign({ 'Content-Type': 'application/json' }, $env.ALERT_LOG_TOKEN ? { 'Authorization': 'Bearer ' + $env.ALERT_LOG_TOKEN } : {}),
    body: rec, timeout: 5000,
  });
} catch (e) { /* fail-open: alert tetap terkirim walau log mati */ }
return [{ json: inp }];
